async ({ workspace: { read, edit, search }, shell: { execFile } }) => {
  const date = (await execFile("date", ["-u", "+%Y-%m-%d"])).stdout.trim();
  await execFile("git", ["checkout", "-b", "release-0.36.2"], { raise: true });
  const subs: [string, string, string][] = [
    ["CHANGELOG.md", "## [Unreleased]\n", `## [Unreleased]\n\n## [0.36.2] - ${date}\n`],
    ["package.json", '"version": "0.36.1"', '"version": "0.36.2"'],
    ["README.md", "pit@v0.36.1", "pit@v0.36.2"],
  ];
  for (const [f, a, b] of subs) {
    const r = await read(f, { format: "raw" });
    if (!r.content.includes(a)) throw new Error(f);
    await edit(f, { revision: r.revision, changes: [{ kind: "replaceFile", content: r.content.replace(a, b) }] });
  }
  const lock = await read("package-lock.json", { format: "raw" });
  const lines = lock.content.split("\n");
  // lines 3 and 9 (1-based)
  for (const i of [2, 8]) { if (!lines[i].includes('"version": "0.36.1"')) throw new Error("lock " + i); lines[i] = lines[i].replace("0.36.1", "0.36.2"); }
  await edit("package-lock.json", { revision: lock.revision, changes: [{ kind: "replaceFile", content: lines.join("\n") }] });
  return date;
}
